footer { font-size: 11px; color: var(--muted); padding: 24px 32px; border-top: 1px solid var(--border); text-align: center; margin-top: 40px; }

/* Concept cards */
.concept-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 12px; margin: 16px 0 24px; }
.concept-card { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 18px 16px 14px; position: relative; }
.concept-card::after { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 3px; border-radius: 0 0 10px 10px; }
.concept-card.c-green::after { background: var(--green); }
.concept-card.c-blue::after { background: var(--accent); }
.concept-card.c-purple::after { background: var(--purple); }
.concept-card.c-orange::after { background: var(--orange); }
.cc-icon { font-size: 26px; margin-bottom: 10px; }
.cc-title { font-size: 13px; font-weight: 700; color: var(--text); margin-bottom: 7px; }
.cc-body { font-size: 12px; color: var(--muted2); line-height: 1.6; }

/* Flow diagram */
.flow-wrap { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 24px 20px; overflow-x: auto; margin: 16px 0; }
.flow-pipeline { display: flex; align-items: center; gap: 0; min-width: 820px; }
